/* Reset & Global */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background-color: #f1f5f9;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 20px;
}

/* Card Container (Box Model + Shadow + Border Radius) */
.card {
  width: 100%;
  max-width: 340px;
  background-color: #ffffff;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.card:hover {
  transform: translateY(-6px);
  box-shadow: 0 20px 30px -10px rgba(0, 0, 0, 0.15);
}

/* Card Header dengan Gradient Background */
.card-header {
  height: 110px;
  background: linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%);
  display: flex;
  justify-content: center;
  align-items: flex-end;
  position: relative;
}

/* Avatar Lingkaran dengan Outline */
.avatar {
  width: 90px;
  height: 90px;
  border-radius: 50%;
  border: 4px solid #ffffff;
  object-fit: cover;
  transform: translateY(45px);
  background-color: #e2e8f0;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

/* Body Card */
.card-body {
  padding: 55px 24px 28px;
  text-align: center;
}

.name {
  font-size: 1.25rem;
  font-weight: 700;
  color: #0f172a;
  margin-bottom: 4px;
}

.role {
  font-size: 0.875rem;
  font-weight: 500;
  color: #3b82f6;
  margin-bottom: 12px;
}

.bio {
  font-size: 0.875rem;
  color: #64748b;
  line-height: 1.5;
  margin-bottom: 20px;
}

/* Statistik Section */
.stats {
  display: flex;
  justify-content: space-around;
  padding: 14px 0;
  margin-bottom: 20px;
  border-top: 1px solid #f1f5f9;
  border-bottom: 1px solid #f1f5f9;
}

.stat-item {
  display: flex;
  flex-direction: column;
}

.stat-num {
  font-size: 1.125rem;
  font-weight: 700;
  color: #0f172a;
}

.stat-label {
  font-size: 0.75rem;
  color: #94a3b8;
  margin-top: 2px;
}

/* Tombol Aksi */
.btn-follow {
  width: 100%;
  padding: 10px 18px;
  font-size: 0.875rem;
  font-weight: 600;
  color: #ffffff;
  background-color: #2563eb;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s ease;
}

.btn-follow:hover {
  background-color: #1d4ed8;
}
